def create_app(*, registry=None, ws_queue_max: int|None=None, **kwargs): import os
app = FastAPI(title="Intraday Trading Platform", version="1.0.0") app.state.task_registry = TaskRegistry() app.state.db_sessionmaker = get_db_sessionmaker()
# Initialize metrics registry app.state.metrics_registry = registry or initialize_metrics_registry()
# Setup model manager based on DISABLE_ML environment variable DISABLE_ML = os.environ.get("DISABLE_ML", "0") == "1" if DISABLE_ML: # Use No-Op model manager with InMemoryModelRegistry for Light Mode from backend.mlops.model_manager import _NoOpModelManager app.state.model_manager = _NoOpModelManager() else: # Use full model manager for production from backend.mlops.model_manager import get_model_manager app.state.model_manager = get_model_manager()
@asynccontextmanager async def lifespan(app): baseline = set(asyncio.all_tasks()) try: yield finally: reg = list(app.state.task_registry.tasks()) new = [t for t in asyncio.all_tasks() if t not in baseline] to_cancel = [t for t in set(reg+new) if not t.done() and not t.cancelled()] for t in to_cancel: try: t.cancel() except: pass if to_cancel: try: await asyncio.wait_for(asyncio.gather(*to_cancel, return_exceptions=True), timeout=2.0) except: pass app.router.lifespan_context = lifespan
# Basic health endpoints @app.get("/health") async def health_check(): return {"status": "healthy", "service": "trading-platform"}
@app.get("/readyz") async def readiness_check(): """ Readiness check endpoint with proper status codes and structured response. Returns 200 when healthy, 503 when unhealthy with detailed checks map. """ import time import json from datetime import datetime from fastapi import Response from backend.infra.db import db_health_check from backend.infra.broker import broker_health_check
timestamp = datetime.utcnow().isoformat() + "Z" checks = {} problems = {} all_healthy = True
# Check database try: db_healthy = await db_health_check() checks["database"] = db_healthy if not db_healthy: all_healthy = False problems["database"] = "Database connection failed" except Exception as e: checks["database"] = False all_healthy = False problems["database"] = f"Database error: {str(e)}"
# Check broker try: broker_healthy = await broker_health_check() checks["broker"] = broker_healthy if not broker_healthy: all_healthy = False problems["broker"] = "Message broker unavailable" except Exception as e: checks["broker"] = False all_healthy = False problems["broker"] = f"Broker error: {str(e)}"
# Prepare response result = { "status": "ready" if all_healthy else "not_ready", "checks": checks, "problems": problems, "timestamp": timestamp }
if not all_healthy: return Response( content=json.dumps(result), status_code=503, media_type="application/json" )
return result
@app.get("/livez") async def liveness_check(): return {"status": "alive", "service": "trading-platform"}
