@asynccontextmanager async def lifespan(app): baseline = set(asyncio.all_tasks()) try: yield finally: reg = list(app.state.task_registry.tasks()) new = [t for t in asyncio.all_tasks() if t not in baseline] to_cancel = [t for t in set(reg+new) if not t.done() and not t.cancelled()] for t in to_cancel: try: t.cancel() except: pass if to_cancel: try: await asyncio.wait_for(asyncio.gather(*to_cancel, return_exceptions=True), timeout=2.0) except: pass app.router.lifespan_context = lifespan
