@app.get("/readyz") async def readiness_check(): """ Readiness check endpoint with proper status codes and structured response. Returns 200 when healthy, 503 when unhealthy with detailed checks map. """ import time import json from datetime import datetime from fastapi import Response from backend.infra.db import db_health_check from backend.infra.broker import broker_health_check
timestamp = datetime.utcnow().isoformat() + "Z" checks = {} problems = {} all_healthy = True
# Check database try: db_healthy = await db_health_check() checks["database"] = db_healthy if not db_healthy: all_healthy = False problems["database"] = "Database connection failed" except Exception as e: checks["database"] = False all_healthy = False problems["database"] = f"Database error: {str(e)}"
# Check broker try: broker_healthy = await broker_health_check() checks["broker"] = broker_healthy if not broker_healthy: all_healthy = False problems["broker"] = "Message broker unavailable" except Exception as e: checks["broker"] = False all_healthy = False problems["broker"] = f"Broker error: {str(e)}"
# Prepare response result = { "status": "ready" if all_healthy else "not_ready", "checks": checks, "problems": problems, "timestamp": timestamp }
if not all_healthy: return Response( content=json.dumps(result), status_code=503, media_type="application/json" )
return result
